insert into partners (id, slug, name, tagline, story, city, instagram, cover, commission_rate, en) values
  ('00000000-0000-4000-8000-000100000001', 'noon-workshop', 'ورشة نون', 'جلد وكروشيه بإيدين بنات أسيوط', 'ورشة صغيرة بدأت في أوضة في بيت، بتعمل أجندات جلد متخيطة يدوي وميداليات كروشيه، كل قطعة بتاخد وقتها.', 'أسيوط', 'noon.workshop', 'https://images.unsplash.com/photo-1531346878377-a5be20888e57?auto=format&fit=crop&w=1200&q=80', 0.2, '{"name":"Noon Workshop","tagline":"Leather and crochet, hand-made in Assiut","story":"A small workshop that started in a bedroom, making hand-stitched leather journals and crochet keychains. Every piece takes its time.","city":"Assiut"}'),
  ('00000000-0000-4000-8000-000100000002', 'saeed-naturals', 'طبيعي من الصعيد', 'صابون وأعشاب من خير الصعيد', 'صابون معمول على البارد بزيت الزيتون، وتشكيلات شاي أعشاب من عطارة العيلة.', 'أبنوب', 'saeed.naturals', 'https://images.unsplash.com/photo-1612817288484-6f916006741a?auto=format&fit=crop&w=1200&q=80', 0.25, '{"name":"Saeed Naturals","tagline":"Soap and herbs from Upper Egypt","story":"Cold-process olive oil soap and herbal tea blends from the family''s spice shop.","city":"Abnub"}'),
  ('00000000-0000-4000-8000-000100000003', 'print-with-love', 'طباعة بحب', 'اسمك على أي حاجة', 'استوديو طباعة صغير بيطبع على المجات والكوشنات والبراويز، وبيبعتلك شكل التصميم توافق عليه الأول.', 'أسيوط', 'printwithlove.ast', 'https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=1200&q=80', 0.2, '{"name":"Print with Love","tagline":"Your name on anything","story":"A small print studio for mugs, cushions and frames. They send you the design to approve first.","city":"Assiut"}'),
  ('00000000-0000-4000-8000-000100000004', 'nour-candles', 'نور للشموع', 'شموع صويا بريحة البيت', 'شموع صويا متصبوبة باليد في برطمانات بتتعاد استخدامها، وريحة على ذوق كل موسم.', 'أسيوط الجديدة', 'nour.candles', 'https://images.unsplash.com/photo-1602874801007-bd458bb1b8b6?auto=format&fit=crop&w=1200&q=80', 0.22, '{"name":"Nour Candles","tagline":"Soy candles that smell like home","story":"Hand-poured soy candles in reusable jars, with scents for every season.","city":"New Assiut"}'),
  ('00000000-0000-4000-8000-000100000005', 'garden-roses', 'ورد الجنينة', 'ورد طبيعي متنسق كل صبح', 'محل ورد عيلة في قلب أسيوط، الورد بيوصل كل صبح وبيتنسق قدام عينك.', 'أسيوط', 'garden.roses.ast', 'https://images.unsplash.com/photo-1563241527-3004b7be0ffd?auto=format&fit=crop&w=1200&q=80', 0.18, '{"name":"Garden Roses","tagline":"Fresh flowers arranged every morning","story":"A family flower shop in the heart of Assiut. Flowers arrive every morning and are arranged in front of you.","city":"Assiut"}'),
  ('00000000-0000-4000-8000-000100000006', 'mira-treats', 'ميرا للحلويات', 'شوكولاتة ومكسرات بلمسة بيتي', 'شوكولاتة بلجيكي متشكلة في مطبخ صغير، ومكسرات بتتحمص على الطلب.', 'منفلوط', 'mira.treats', 'https://images.unsplash.com/photo-1599599810769-bcde5a160d32?auto=format&fit=crop&w=1200&q=80', 0.2, '{"name":"Mira Treats","tagline":"Chocolate and nuts with a homemade touch","story":"Belgian chocolate shaped in a small kitchen, and nuts roasted to order.","city":"Manfalut"}'),
  ('00000000-0000-4000-8000-000100000007', 'wood-carve', 'خشب ونقش', 'حفر بالليزر على الخشب الطبيعي', 'ورشة خشب بتحفر الأسامي والتواريخ على ميداليات وبراويز من خشب طبيعي.', 'أسيوط', 'wood.carve', 'https://images.unsplash.com/photo-1513201099705-a9746e1e201f?auto=format&fit=crop&w=1200&q=80', 0.2, '{"name":"Wood & Carve","tagline":"Laser engraving on natural wood","story":"A wood workshop engraving names and dates on natural wood keychains and frames.","city":"Assiut"}'),
  ('00000000-0000-4000-8000-000100000008', 'little-stitch', 'ليتل ستيتش', 'تطريز وهدايا للمواليد', 'أم بتطرّز أسامي المواليد على بطاطين قطن، ومعاها دباديب طرية للبيبي.', 'ديروط', 'little.stitch', 'https://images.unsplash.com/photo-1522771930-78848d9293e8?auto=format&fit=crop&w=1200&q=80', 0.2, '{"name":"Little Stitch","tagline":"Embroidery and gifts for new babies","story":"A mom who embroiders babies'' names on cotton blankets, with soft teddy bears to match.","city":"Dayrout"}');
insert into products (id, slug, name, description, images, price, cost, category, partner_id, brand, occasions, recipients, interests, is_customizable, customization_max_chars, prep_days, is_available, is_addon, box_eligible, en) values
  ('00000000-0000-4000-8000-000200000001', 'name-mug', 'مج مطبوع بالاسم', 'مج سيراميك أبيض مطبوع عليه الاسم أو جملة قصيرة تختارها.', array['https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=1200&q=80']::text[], 180, 99, 'مجات', '00000000-0000-4000-8000-000100000003', null, array['birthday', 'success', 'thanks', 'mothers-day']::text[], array['her', 'him', 'mom', 'dad', 'colleague']::text[], array['قهوة', 'شاي']::text[], true, 25, 2, true, false, true, '{"name":"Personalised name mug","description":"A white ceramic mug printed with a name or a short line of your choice.","category":"Mugs"}'),
  ('00000000-0000-4000-8000-000200000002', 'scented-candle', 'شمعة معطرة في برطمان', 'شمعة صويا بريحة فانيليا وعود، بتولع حوالي 30 ساعة.', array['https://images.unsplash.com/photo-1602874801007-bd458bb1b8b6?auto=format&fit=crop&w=1200&q=80']::text[], 220, 121, 'شموع', '00000000-0000-4000-8000-000100000004', null, array['birthday', 'thanks', 'mothers-day', 'christmas', 'engagement']::text[], array['her', 'mom', 'colleague']::text[], array['ديكور', 'استرخاء']::text[], false, null, 0, true, false, true, '{"name":"Scented candle jar","description":"Vanilla and oud soy candle, burns for about 30 hours.","category":"Candles"}'),
  ('00000000-0000-4000-8000-000200000003', 'rose-bouquet', 'بوكيه ورد طبيعي', 'بوكيه 12 وردة طبيعي متنسق ومتغلف.', array['https://images.unsplash.com/photo-1563241527-3004b7be0ffd?auto=format&fit=crop&w=1200&q=80']::text[], 450, 248, 'ورد', '00000000-0000-4000-8000-000100000005', null, array['birthday', 'engagement', 'get-well', 'mothers-day', 'thanks']::text[], array['her', 'mom']::text[], array['ورد']::text[], false, null, 0, true, false, false, '{"name":"Fresh rose bouquet","description":"A wrapped bouquet of 12 fresh roses.","category":"Flowers"}'),
  ('00000000-0000-4000-8000-000200000004', 'single-rose', 'وردة طبيعي', 'وردة واحدة متغلفة بشريطة.', array['https://images.unsplash.com/photo-1527061011665-3652c757a4d4?auto=format&fit=crop&w=1200&q=80']::text[], 60, 33, 'ورد', '00000000-0000-4000-8000-000100000005', null, array['birthday', 'engagement', 'thanks']::text[], array['her', 'mom']::text[], array['ورد']::text[], false, null, 0, true, true, true, '{"name":"Single fresh rose","description":"One rose, wrapped and tied with a ribbon.","category":"Flowers"}'),
  ('00000000-0000-4000-8000-000200000005', 'chocolate-box', 'علبة شوكولاتة فاخرة', '16 قطعة شوكولاتة بلجيكي بحشوات مختلفة.', array['https://images.unsplash.com/photo-1599599810769-bcde5a160d32?auto=format&fit=crop&w=1200&q=80']::text[], 250, 138, 'شوكولاتة', '00000000-0000-4000-8000-000100000006', null, array['birthday', 'success', 'thanks', 'christmas', 'engagement']::text[], array['her', 'him', 'mom', 'dad', 'kid', 'colleague']::text[], array['حلويات']::text[], false, null, 0, true, true, true, '{"name":"Luxury chocolate box","description":"16 Belgian chocolates with assorted fillings.","category":"Chocolate"}'),
  ('00000000-0000-4000-8000-000200000006', 'helium-balloon', 'بالونة هيليوم', 'بالونة هيليوم مكتوب عليها حسب المناسبة.', array['https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1200&q=80']::text[], 90, 50, 'بالونات', null, null, array['birthday', 'success', 'newborn']::text[], array['her', 'him', 'kid']::text[], array[]::text[], false, null, 0, true, true, false, '{"name":"Helium balloon","description":"A helium balloon printed for the occasion.","category":"Balloons"}'),
  ('00000000-0000-4000-8000-000200000007', 'engraved-keychain', 'ميدالية خشب محفورة', 'ميدالية خشب طبيعي محفور عليها الاسم أو التاريخ.', array['https://images.unsplash.com/photo-1513201099705-a9746e1e201f?auto=format&fit=crop&w=1200&q=80']::text[], 150, 83, 'ميداليات', '00000000-0000-4000-8000-000100000007', null, array['birthday', 'success', 'engagement', 'thanks']::text[], array['her', 'him', 'colleague']::text[], array[]::text[], true, 15, 3, true, false, true, '{"name":"Engraved wooden keychain","description":"Natural wood keychain engraved with a name or a date.","category":"Keychains"}'),
  ('00000000-0000-4000-8000-000200000008', 'printed-cushion', 'كوشن مطبوع', 'كوشن قطيفة 40×40 مطبوع عليه جملة تختارها.', array['https://images.unsplash.com/photo-1584100936595-c0654b55a2e2?auto=format&fit=crop&w=1200&q=80']::text[], 280, 154, 'ديكور', '00000000-0000-4000-8000-000100000003', null, array['birthday', 'mothers-day', 'engagement']::text[], array['her', 'mom', 'kid']::text[], array['ديكور']::text[], true, 40, 3, true, false, true, '{"name":"Printed cushion","description":"40×40 velvet cushion printed with your words.","category":"Home"}'),
  ('00000000-0000-4000-8000-000200000009', 'leather-notebook', 'أجندة جلد هاند ميد', 'أجندة جلد طبيعي متخيطة يدوي، 120 ورقة.', array['https://images.unsplash.com/photo-1531346878377-a5be20888e57?auto=format&fit=crop&w=1200&q=80']::text[], 320, 176, 'أدوات مكتب', '00000000-0000-4000-8000-000100000001', null, array['success', 'thanks', 'birthday']::text[], array['him', 'her', 'colleague', 'dad']::text[], array['كتابة', 'قراءة']::text[], true, 20, 2, true, false, true, '{"name":"Handmade leather journal","description":"Hand-stitched genuine leather journal, 120 pages.","category":"Stationery"}'),
  ('00000000-0000-4000-8000-000200000010', 'crochet-keychain', 'ميدالية كروشيه', 'ميدالية كروشيه معمولة باليد، أشكال مختلفة.', array['https://images.unsplash.com/photo-1584992236310-6edddc08acff?auto=format&fit=crop&w=1200&q=80']::text[], 120, 66, 'ميداليات', '00000000-0000-4000-8000-000100000001', null, array['birthday', 'success', 'thanks']::text[], array['her', 'kid']::text[], array['هاند ميد']::text[], false, null, 0, true, false, true, '{"name":"Crochet keychain","description":"Hand-made crochet keychain in different shapes.","category":"Keychains"}'),
  ('00000000-0000-4000-8000-000200000011', 'soap-set', 'طقم صابون طبيعي', '3 قطع صابون طبيعي بزيت الزيتون واللافندر.', array['https://images.unsplash.com/photo-1612817288484-6f916006741a?auto=format&fit=crop&w=1200&q=80']::text[], 190, 105, 'عناية', '00000000-0000-4000-8000-000100000002', null, array['mothers-day', 'thanks', 'get-well']::text[], array['her', 'mom']::text[], array['عناية', 'استرخاء']::text[], false, null, 0, true, false, true, '{"name":"Natural soap set","description":"3 natural soaps with olive oil and lavender.","category":"Self-care"}'),
  ('00000000-0000-4000-8000-000200000012', 'teddy-bear', 'دبدوب قطيفة', 'دبدوب قطيفة طري 35 سم.', array['https://images.unsplash.com/photo-1559454403-b8fb88521f11?auto=format&fit=crop&w=1200&q=80']::text[], 300, 165, 'ألعاب', '00000000-0000-4000-8000-000100000008', null, array['birthday', 'newborn', 'get-well', 'engagement']::text[], array['her', 'kid']::text[], array[]::text[], false, null, 0, true, false, true, '{"name":"Velvet teddy bear","description":"A soft 35 cm velvet teddy bear.","category":"Toys"}'),
  ('00000000-0000-4000-8000-000200000013', 'nuts-box', 'علبة مكسرات مشكلة', 'نص كيلو مكسرات محمصة في علبة هدايا.', array['https://images.unsplash.com/photo-1508061253366-f7da158b6d46?auto=format&fit=crop&w=1200&q=80']::text[], 230, 127, 'أكل', '00000000-0000-4000-8000-000100000006', null, array['thanks', 'get-well', 'ramadan', 'christmas']::text[], array['mom', 'dad', 'colleague', 'him']::text[], array['أكل']::text[], false, null, 0, true, false, true, '{"name":"Mixed nuts box","description":"Half a kilo of roasted nuts in a gift box.","category":"Treats"}'),
  ('00000000-0000-4000-8000-000200000014', 'photo-frame', 'برواز صورة مطبوع', 'برواز خشب 20×25 بالصورة اللي تبعتها.', array['https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1200&q=80']::text[], 200, 110, 'ديكور', '00000000-0000-4000-8000-000100000003', null, array['birthday', 'mothers-day', 'engagement', 'newborn']::text[], array['her', 'mom', 'dad']::text[], array['ذكريات']::text[], true, 30, 2, true, false, true, '{"name":"Printed photo frame","description":"A 20×25 wooden frame with the photo you send us.","category":"Home"}'),
  ('00000000-0000-4000-8000-000200000015', 'christmas-ornaments', 'طقم زينة الكريسماس', '6 كور زينة للشجرة بألوان دهبي وأحمر.', array['https://images.unsplash.com/photo-1543589077-47d81606c1bf?auto=format&fit=crop&w=1200&q=80']::text[], 160, 88, 'زينة', null, null, array['christmas']::text[], array['her', 'mom', 'kid']::text[], array['ديكور']::text[], false, null, 0, true, false, true, '{"name":"Christmas ornament set","description":"6 gold and red tree ornaments.","category":"Decor"}'),
  ('00000000-0000-4000-8000-000200000016', 'baby-blanket', 'بطانية مولود مطرزة', 'بطانية قطن ناعمة مطرز عليها اسم المولود.', array['https://images.unsplash.com/photo-1522771930-78848d9293e8?auto=format&fit=crop&w=1200&q=80']::text[], 380, 209, 'مواليد', '00000000-0000-4000-8000-000100000008', null, array['newborn']::text[], array['kid']::text[], array[]::text[], true, 12, 4, true, false, true, '{"name":"Embroidered baby blanket","description":"A soft cotton blanket embroidered with the baby''s name.","category":"Baby"}'),
  ('00000000-0000-4000-8000-000200000017', 'herbal-tea', 'علبة شاي أعشاب', 'تشكيلة 4 أنواع شاي أعشاب في علبة خشب.', array['https://images.unsplash.com/photo-1576092768241-dec231879fc3?auto=format&fit=crop&w=1200&q=80']::text[], 170, 94, 'أكل', '00000000-0000-4000-8000-000100000002', null, array['get-well', 'thanks', 'mothers-day']::text[], array['mom', 'dad', 'colleague']::text[], array['شاي', 'استرخاء']::text[], false, null, 0, true, false, true, '{"name":"Herbal tea box","description":"4 herbal teas in a wooden box.","category":"Treats"}');
