  ('00000000-0000-4000-8000-000300000001', 'christmas-2027', 'الكريسماس ورأس السنة', 'christmas', '2027-01-07', '2026-12-28T21:00:00+02:00', '2027-01-05T21:00:00+02:00', '2026-10-01T00:00:00+02:00', '2027-01-07T23:59:00+02:00', 'هدايا الكريسماس ورأس السنة', 'باكدجات جاهزة ومتغلفة، توصل لحد البيت في أسيوط', 'https://images.unsplash.com/photo-1513885535751-8b9238bd345a?auto=format&fit=crop&w=1200&q=80', '{"name":"Christmas & New Year","bannerTitle":"Christmas & New Year gifts","bannerSubtitle":"Ready, wrapped packages delivered to the door in Assiut"}');
insert into packages (id, slug, name, description, images, tier, price, season_id, occasions, recipients, en) values
  ('00000000-0000-4000-8000-000400000001', 'birthday-latif', 'عيد ميلاد سعيد', 'مج بالاسم وشوكولاتة وبالونة، بداية لطيفة ليوم حلو.', array['https://images.unsplash.com/photo-1549465220-1a8b9238cd48?auto=format&fit=crop&w=1200&q=80']::text[], 'latif', 590, null, array['birthday']::text[], array['her', 'him', 'colleague']::text[], '{"name":"Happy Birthday","description":"A name mug, chocolates and a balloon: a sweet start to a lovely day."}'),
  ('00000000-0000-4000-8000-000400000002', 'birthday-momayaz', 'عيد ميلاد مميز', 'بوكيه ورد وشمعة معطرة وشوكولاتة في بوكس واحد.', array['https://images.unsplash.com/photo-1608755728617-aefab37d2edd?auto=format&fit=crop&w=1200&q=80']::text[], 'momayaz', 1050, null, array['birthday', 'engagement']::text[], array['her', 'mom']::text[], '{"name":"Birthday Deluxe","description":"Fresh roses, a scented candle and chocolates in one box."}'),
  ('00000000-0000-4000-8000-000400000003', 'get-well-soon', 'سلامتك', 'شاي أعشاب ومكسرات ووردة، عشان يحس إنك جنبه.', array['https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=1200&q=80']::text[], 'latif', 520, null, array['get-well']::text[], array['mom', 'dad', 'colleague', 'her', 'him']::text[], '{"name":"Get Well Soon","description":"Herbal tea, nuts and a rose, so they know you''re there."}'),
  ('00000000-0000-4000-8000-000400000004', 'success-box', 'مبروك النجاح', 'أجندة جلد هاند ميد وميدالية محفورة وشوكولاتة.', array['https://images.unsplash.com/photo-1512909006721-3d6018887383?auto=format&fit=crop&w=1200&q=80']::text[], 'momayaz', 820, null, array['success']::text[], array['her', 'him']::text[], '{"name":"Congrats Grad","description":"A handmade leather journal, an engraved keychain and chocolates."}'),
  ('00000000-0000-4000-8000-000400000005', 'newborn-welcome', 'أهلاً بالمولود', 'بطانية مطرزة باسم المولود ودبدوب وبالونة.', array['https://images.unsplash.com/photo-1559454403-b8fb88521f11?auto=format&fit=crop&w=1200&q=80']::text[], 'fakher', 890, null, array['newborn']::text[], array['kid']::text[], '{"name":"Welcome Baby","description":"A blanket embroidered with the baby''s name, a teddy bear and a balloon."}'),
  ('00000000-0000-4000-8000-000400000006', 'for-mom', 'لست الحبايب', 'كوشن مطبوع وطقم صابون طبيعي وبوكيه ورد.', array['https://images.unsplash.com/photo-1561181286-d3fee7d55364?auto=format&fit=crop&w=1200&q=80']::text[], 'fakher', 1080, null, array['mothers-day', 'birthday']::text[], array['mom']::text[], '{"name":"For the Best Mom","description":"A printed cushion, natural soaps and a rose bouquet."}'),
  ('00000000-0000-4000-8000-000400000007', 'student-budget', 'هدية طالب', 'ميدالية كروشيه ووردة وشوكولاتة، على قد الإيد.', array['https://images.unsplash.com/photo-1513201099705-a9746e1e201f?auto=format&fit=crop&w=1200&q=80']::text[], 'latif', 450, null, array['birthday', 'success', 'thanks']::text[], array['her', 'him']::text[], '{"name":"Student Treat","description":"A crochet keychain, a rose and chocolates, easy on the budget."}'),
  ('00000000-0000-4000-8000-000400000008', 'christmas-joy', 'فرحة الكريسماس', 'زينة للشجرة وشمعة معطرة وشوكولاتة.', array['https://images.unsplash.com/photo-1603006905003-be475563bc59?auto=format&fit=crop&w=1200&q=80']::text[], 'momayaz', 720, '00000000-0000-4000-8000-000300000001', array['christmas']::text[], array['her', 'mom', 'kid']::text[], '{"name":"Christmas Joy","description":"Tree ornaments, a scented candle and chocolates."}'),
  ('00000000-0000-4000-8000-000400000009', 'christmas-family', 'سفرة العيد', 'مكسرات وشوكولاتة وشمعة وزينة، هدية للبيت كله.', array['https://images.unsplash.com/photo-1513885535751-8b9238bd345a?auto=format&fit=crop&w=1200&q=80']::text[], 'fakher', 980, '00000000-0000-4000-8000-000300000001', array['christmas']::text[], array['mom', 'dad']::text[], '{"name":"Holiday Table","description":"Nuts, chocolates, a candle and ornaments: a gift for the whole home."}');
