insert into kits (id, category, role, slug, name, tagline, description, images, price_per_person, min_people, max_people, contents, duration, prep_days, sort, en) values
  ('00000000-0000-4000-8000-000700000001', 'workshop', null, 'paint-hairbrush', 'كيت تلوين فرشة الشعر', 'كل واحدة ترسم فرشتها على ذوقها', 'فرشة ومشط خشب طبيعي تلوّنيهم بإيدك مع صحابك، وكل كيت متغلف في شنطة قماش بفيونكة وكارت باسم صاحبته.', array['https://images.unsplash.com/photo-1512909006721-3d6018887383?auto=format&fit=crop&w=1200&q=80']::text[], 280, 3, 25, array['فرشة شعر خشب', 'مشط خشب', '4 ألوان أكريليك', '2 فرشة رسم', 'باليتة ألوان', 'شنطة قماش بفيونكة', 'كارت بالاسم']::text[], 'ساعة ونص تقريباً', 3, 0, '{"name":"Paint-your-hairbrush kit","tagline":"Everyone paints her own brush","description":"A natural wooden brush and comb to paint with your friends. Each kit comes in a cotton bag with a bow and a name card.","contents":["Wooden hairbrush","Wooden comb","4 acrylic paints","2 paint brushes","Paint palette","Cotton bag with a bow","Name card"],"duration":"About 1.5 hours"}'),
  ('00000000-0000-4000-8000-000700000002', 'workshop', null, 'diy-earrings', 'كيت حلقان DIY', 'اعملي حلقانك بإيدك', 'خرز وحلقات وكل الأدوات عشان كل واحدة تعمل جوز حلقان أو أكتر، في علبة كرافت مطبوعة.', array['https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=1200&q=80']::text[], 320, 3, 25, array['خرز ألوان مختلفة', 'حلقات وخطافات', 'زرادية صغيرة', 'سلك تشكيل', 'علبة تخزين', 'كارت خطوات', 'كارت بالاسم']::text[], 'ساعة تقريباً', 3, 1, '{"name":"DIY earrings kit","tagline":"Make your own earrings","description":"Beads, hoops and all the tools for everyone to make a pair or more, in a printed kraft box.","contents":["Assorted beads","Hoops and hooks","Mini pliers","Shaping wire","Storage box","Step-by-step card","Name card"],"duration":"About 1 hour"}'),
  ('00000000-0000-4000-8000-000700000003', 'workshop', null, 'candle-making', 'كيت شمع معطّر', 'شمعتك بريحتك', 'شمع صويا وزيوت عطرية وبرطمان، كل واحدة تختار الريحة وتصب شمعتها وتاخدها معاها.', array['https://images.unsplash.com/photo-1602874801007-bd458bb1b8b6?auto=format&fit=crop&w=1200&q=80']::text[], 350, 3, 20, array['شمع صويا', 'برطمان إزاز', 'فتيلة خشب', '2 زيت عطري', 'عصاية تقليب', 'ستيكر للبرطمان', 'كارت بالاسم']::text[], 'ساعة تقريباً', 4, 2, '{"name":"Candle-making kit","tagline":"Your candle, your scent","description":"Soy wax, fragrance oils and a jar. Everyone picks a scent, pours her candle and takes it home.","contents":["Soy wax","Glass jar","Wooden wick","2 fragrance oils","Stirring stick","Jar sticker","Name card"],"duration":"About 1 hour"}'),
  ('00000000-0000-4000-8000-000700000004', 'workshop', null, 'paint-tote', 'كيت تلوين شنطة قماش', 'شنطة محدش عنده زيها', 'شنطة قماش سادة وألوان قماش مبتتغسلش واستنسل رسومات، تنفع لأي قعدة بنات.', array['https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=1200&q=80']::text[], 220, 3, 30, array['شنطة قماش', '5 ألوان قماش', '2 فرشة', 'استنسل رسومات', 'كرتونة حماية', 'كارت بالاسم']::text[], 'ساعة تقريباً', 2, 3, '{"name":"Paint-a-tote kit","tagline":"A bag nobody else has","description":"A plain cotton tote, washable fabric paints and stencils. Perfect for any girls'' night.","contents":["Cotton tote bag","5 fabric paints","2 brushes","Design stencils","Protective card","Name card"],"duration":"About 1 hour"}'),
  ('00000000-0000-4000-8000-000700000005', 'workshop', null, 'paint-mug', 'كيت تلوين مج', 'مجك بإيدك', 'مج سيراميك أبيض وأقلام سيراميك، ترسمي وتكتبي اللي نفسك فيه، وبيتثبت في الفرن في البيت.', array['https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=1200&q=80']::text[], 240, 3, 30, array['مج سيراميك أبيض', '4 أقلام سيراميك', 'ورقة أفكار رسومات', 'علبة هدية', 'كارت بالاسم']::text[], '45 دقيقة تقريباً', 2, 4, '{"name":"Paint-a-mug kit","tagline":"Your mug, by hand","description":"A white ceramic mug and ceramic markers. Draw or write anything, then set it in your oven at home.","contents":["White ceramic mug","4 ceramic markers","Design ideas sheet","Gift box","Name card"],"duration":"About 45 minutes"}'),
  ('00000000-0000-4000-8000-000800000001', 'bridal', 'bridesmaid', 'bridesmaid-proposal', 'بوكس هتكوني إشبينتي؟', 'اسأليها بطريقة متتنسيش', 'بوكس بتفتحه صاحبتك وتلاقي جواه السؤال: هتكوني إشبينتي؟ ومعاه حاجات باسمها تفضل معاها بعد الفرح.', array['https://images.unsplash.com/photo-1549465220-1a8b9238cd48?auto=format&fit=crop&w=1200&q=80']::text[], 650, 1, 12, array['كارت «هتكوني إشبينتي؟»', 'روب ساتان مطرز بالاسم', 'تمبلر بالاسم', 'سكرانشي ساتان', 'شمعة صغيرة', 'بوكس بفيونكة']::text[], '', 5, 5, '{"name":"Will you be my bridesmaid? box","tagline":"Ask her in a way she won''t forget","description":"A box your friend opens to find the question: will you be my bridesmaid? Plus gifts with her name to keep after the wedding.","contents":["\"Will you be my bridesmaid?\" card","Satin robe embroidered with her name","Name tumbler","Satin scrunchie","Mini candle","Box with a bow"]}'),
  ('00000000-0000-4000-8000-000800000002', 'bridal', 'bridesmaid', 'wedding-day-squad', 'بوكس يوم الفرح للإشبينات', 'جاهزين للصور من الصبح', 'كل اللي الإشبينات محتاجينه يوم الفرح: روب بالاسم للصور، وحاجات صغيرة تريحهم طول اليوم.', array['https://images.unsplash.com/photo-1608755728617-aefab37d2edd?auto=format&fit=crop&w=1200&q=80']::text[], 550, 2, 12, array['روب ساتان بالاسم', 'شبشب قطيفة', 'ماسك عين', 'سكرانشي', 'ميني بيرفيوم', 'كارت شكر من العروسة']::text[], '', 5, 6, '{"name":"Bridesmaids'' wedding-day box","tagline":"Photo-ready from the morning","description":"Everything the bridesmaids need on the day: a name robe for the photos and little comforts for the whole day.","contents":["Satin name robe","Velvet slippers","Eye mask","Scrunchie","Mini perfume","Thank-you card from the bride"]}'),
  ('00000000-0000-4000-8000-000800000003', 'bridal', 'bride', 'bride-box', 'بوكس العروسة', 'ليكي إنتي يا عروسة', 'هدية العروسة نفسها، من صاحبتها أو من العريس: روب Bride وشماعة فستان باسمها وحاجات ليوم العمر.', array['https://images.unsplash.com/photo-1606800052052-a08af7148866?auto=format&fit=crop&w=1200&q=80']::text[], 1200, 1, 1, array['روب ساتان Bride', 'شماعة فستان باسمها', 'تمبلر Bride to be', 'تاج صغير', 'شمعة معطرة', 'كارت برسالتك']::text[], '', 5, 7, '{"name":"Bride box","tagline":"Just for you, bride","description":"A gift for the bride herself, from her best friend or the groom: a Bride robe, a dress hanger with her name and treats for the big day.","contents":["Satin Bride robe","Dress hanger with her name","Bride-to-be tumbler","Mini tiara","Scented candle","Card with your message"]}'),
  ('00000000-0000-4000-8000-000800000004', 'bridal', 'mother', 'mother-of-bride', 'هدية أم العروسة', 'شكراً يا ماما', 'هدية شكر لأم العروسة أو أم العريس: شال وبرواز بصورتكم وكارت بكلمة من القلب.', array['https://images.unsplash.com/photo-1561181286-d3fee7d55364?auto=format&fit=crop&w=1200&q=80']::text[], 750, 1, 2, array['شال ناعم', 'برواز بصورتكم', 'شمعة معطرة', 'كارت شكر']::text[], '', 4, 8, '{"name":"Mother of the bride gift","tagline":"Thank you, Mom","description":"A thank-you for the mother of the bride or groom: a soft shawl, a framed photo of you and a heartfelt card.","contents":["Soft shawl","Framed photo","Scented candle","Thank-you card"]}'),
  ('00000000-0000-4000-8000-000800000005', 'bridal', 'flower-girl', 'flower-girl', 'بوكس الفلاور جيرل', 'لأصغر واحدة في الفرح', 'تاج ورد وشنطة صغيرة باسمها ودبدوب، عشان تحس إنها أميرة الفرح.', array['https://images.unsplash.com/photo-1559454403-b8fb88521f11?auto=format&fit=crop&w=1200&q=80']::text[], 420, 1, 6, array['تاج ورد', 'شنطة صغيرة بالاسم', 'دبدوب صغير', 'كارت ملون']::text[], '', 4, 9, '{"name":"Flower girl box","tagline":"For the littlest one at the wedding","description":"A flower crown, a little bag with her name and a teddy, so she feels like the princess of the day.","contents":["Flower crown","Little name bag","Small teddy","Colourful card"]}');
